"""Emission compliance tests for root (auto-generated by pact)."""

from root.root import Root


class TestEmissionCompliance:
    """Verify root emits structured events correctly."""

    def _make_handler(self):
        events = []
        return events, lambda event: events.append(event)

    def test_verify_http_api_contract_emits_events(self):
        """Method verify_http_api_contract emits invoked and completed events."""
        events, handler = self._make_handler()
        obj = Root(event_handler=handler)
        try:
            obj.verify_http_api_contract()
        except (TypeError, Exception):
            pass
        invoked = [e for e in events if e.get("event") == "invoked"]
        completed = [e for e in events if e.get("event") in ("completed", "error")]
        assert len(invoked) >= 1, 'No invoked event for verify_http_api_contract'
        assert len(completed) >= 1, 'No completed/error event for verify_http_api_contract'
        assert invoked[0].get("pact_key") == "PACT:root:verify_http_api_contract"
        assert isinstance(invoked[0].get("input_classification"), list)

